// ---- Objects ----

export type WireObjectType =
  | 'game'
  | 'player'
  | 'card'
  | 'cardState'
  | 'stackItem';

/** A change to some properties; null puts a property back to its default. */
export type Patch<P> = { [K in keyof P]?: P[K] | null };

export type WireObject =
  | { type: 'game'; id: GameId; props: GameProps }
  | { type: 'player'; id: PlayerId; props: PlayerProps }
  | { type: 'card'; id: CardId; props: CardProps }
  | { type: 'cardState'; id: CardId; state: CardStateName; props: CardStateProps }
  | { type: 'stackItem'; id: StackItemId; props: StackItemProps };

export type WireObjectPatch =
  | { type: 'game'; id: GameId; props: Patch<GameProps> }
  | { type: 'player'; id: PlayerId; props: Patch<PlayerProps> }
  | { type: 'card'; id: CardId; props: Patch<CardProps> }
  | { type: 'cardState'; id: CardId; state: CardStateName; props: Patch<CardStateProps> }
  | { type: 'stackItem'; id: StackItemId; props: Patch<StackItemProps> };

// ---- Envelope: server -> client JSON text frames ----

export interface LogEntry {
  type: GameLogEntryType;
  msg: string;
}

/** Once per connection, first. */
export interface HelloMessage {
  t: 'hello';
  /** Wire format version (WIRE_VERSION). */
  v: 2;
  hidden: HiddenPolicy;
  /** Runtime kind of every property; compare with PROPERTY_KINDS. */
  schema: Record<string, WireKind>;
}

/** On connect and at each new game: replaces all state. */
export interface SnapshotMessage {
  t: 'snapshot';
  /** Game number in this server run. */
  game: number;
  /** The next delta has seq + 1. */
  seq: number;
  label: string;
  /** Whose stream this is (Viewer.toJson); omniscient = debug FULL policy. */
  viewer: { seat: number; player: number; omniscient?: true } | { spectator: true; omniscient?: true };
  objects: WireObject[];
  /** Tail of the game log, oldest first. */
  log: LogEntry[];
  /** Times the first player has started a turn (RoundCounter); absent before turn 1. */
  round?: number;
}

/** Apply `new` (replaces the whole object), then `changed` (merge; null = back to default), then `removed`. */
export interface DeltaMessage {
  t: 'delta';
  game: number;
  /** Previous seq + 1. */
  seq: number;
  /** Server time, epoch ms. */
  ts: number;
  new: WireObject[];
  changed: WireObjectPatch[];
  /** Object keys: `type:id`, or `cardState:id:State`. */
  removed: string[];
  /** Log entries since the previous message. */
  log: LogEntry[];
  /** Engine event class names without the `GameEvent` prefix. */
  events: string[];
  /** The new round, when it changed (RoundCounter). */
  round?: number;
  /** Last delta of the game. */
  final?: true;
}

export type ServerMessage = HelloMessage | SnapshotMessage | DeltaMessage;

// ---- Protocol (ProtocolMethod). Arguments are positional; unknown = no wire form yet ----

/** Who calls each method: 'server' = game to player (IGuiGame), 'client' = player to game (IGameController). */
