  sideboard: [unknown[], unknown[], string];
  chooseSingleEntityForEffect: [string, unknown[], unknown /* DelayedReveal */, boolean];
  chooseEntitiesForEffect: [string, unknown[], number, number, unknown /* DelayedReveal */];
